INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-leon-mohammed-cie318', 'stk-leon-mohammed', 'CIE 318', 'doc', '{"docs": [{"id": "stk-dr-f172119", "n": "Dr. Nezar Yazidi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "CIE-318 term 212\nالتحضير: كل يوم نهاية المحاضرة والدكتور ماشاء الله يحفظك من ثاني محاضرة.\n\nالكوزيزات: الكوزات على حسب شهوة الدكتور مرة يحدد تاريخ ويحدد المحتوى ومرات من الفقرة الي يشرحها في المحاضرة (عادي تستعين بصديق) والاغلب ياخذ درجات عالية.\n\nالمادة كانت مياجر والمياجر اذا ذاكرت الي يشرحه وركزت معاه في المحاضرة اضمن لك الفل مارك\n\nالمشروع: المشروع لازم تحدده في الفترة المحددة من الدكتور وطبعا لازم تجيب مشروع له علاقة بالمادة لو بشي بسيط\n\nالفاينل: الفاينل كان حرفيا عبارة عن سلايدات.\n\nإضافات: الدكتور الصراحة قليل في حقه إن نقول عليه اسطوري الدكتور اكثر من اسطوري, التصحيح جبار( يعطيك حقك وأكثر ) وغالبا يدف في نهاية الترم , اذا شفت الدكتور منزل لاتتردد في في إنك تنزل عنده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534649-cie318", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/nezar-yazidi/172119/6", "user": "Leon-Mohammed", "ts": 1655277844000, "tid": 172119, "pn": 6}}]}', 1655277844000, 1794774613, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
COMMIT;
